insert into public.exam_questions (id, module, question, options, answer, explanation) values
  (127, 'professione', 'Hai l''attestato di un corso privato di ricostruzione unghie, come NailX. Cosa ti permette?', '["Aprire un nail center in proprio con la SCIA","Fare da responsabile tecnico di un centro","Documentare nel curriculum una formazione professionalizzante, senza abilitarti","Lavorare in proprio solo in alcune Regioni"]'::jsonb, 2, 'Un attestato privato documenta competenze e ore di formazione ma non è abilitante: per lavorare in proprio servono la qualifica di estetista, il responsabile tecnico e la SCIA. Ad oggi nessun atto regionale ufficiale prevede eccezioni.'),
  (128, 'professione', 'Cosa NON serve nella scheda cliente?', '["Allergie","Farmaci e patologie","Il colore preferito dell''auto","Consenso privacy"]'::jsonb, 2, 'La scheda raccoglie dati utili alla sicurezza del servizio.'),
  (129, 'professione', 'Allergie, farmaci e gravidanza scritti nella scheda cliente sono…', '["Dati qualunque","Dati relativi alla salute, protetti in modo particolare dal GDPR","Dati pubblici","Dati fiscali"]'::jsonb, 1, 'Sono "categorie particolari" (art. 9 GDPR): servono informativa, consenso esplicito e custodia sicura.'),
  (130, 'professione', 'Per pubblicare sui social la foto delle mani di una cliente serve…', '["Niente, se le unghie le ho fatte io","Un consenso separato e specifico, che la cliente può rifiutare","Solo la firma sulla scheda del servizio","Il permesso del Comune"]'::jsonb, 1, 'La foto non è necessaria al servizio: serve un consenso a parte. Garante e Cassazione si sono espressi su casi simili.'),
  (131, 'professione', 'Quale consiglio dai dopo il trattamento?', '["Usare le unghie per aprire le lattine","Olio per cuticole ogni giorno e guanti per i lavori domestici","Staccare da sola il prodotto","Saltare il refill"]'::jsonb, 1, 'Cura quotidiana e protezione allungano la durata.'),
  (132, 'professione', 'Quale foto mostra meglio la posizione dell''apex?', '["Dall''alto","Di profilo","Da lontano con la cliente in posa","Con un filtro colorato"]'::jsonb, 1, 'Dall''alto si vedono forma e smile line; a tunnel la curva a C; di profilo apex e spessore.'),
  (133, 'professione', 'Prezzo indicativo di un refill in Italia?', '["5 €","25–35 €","150 €","300 €"]'::jsonb, 1, 'Ordine di grandezza da articoli e testimonianze 2021–2025; i prezzi variano molto per zona e centro.'),
  (134, 'professione', 'Come si calcola il costo dei materiali per servizio?', '["Prezzo del gel diviso per 10","Spesa mensile per i prodotti divisa per il numero di clienti del mese","Si copia il prezzo della concorrenza","Non serve calcolarlo"]'::jsonb, 1, 'Meglio fare la media su più mesi per tener conto dei periodi più o meno pieni.'),
  (135, 'professione', 'Nel regime forfettario, su cosa si calcolano imposta e contributi di un''estetista?', '["Su tutti gli incassi","Sul 67% degli incassi (coefficiente di redditività)","Solo sugli incassi in contanti","Sul guadagno dopo aver tolto le spese reali"]'::jsonb, 1, 'Le spese reali non si scaricano: sono comprese forfettariamente nel 33% non tassato.'),
  (136, 'professione', 'I contributi INPS fissi degli artigiani…', '["Si pagano solo se si guadagna più di 85.000 €","Si pagano sul minimale anche se si guadagna meno","Non esistono in forfettario","Si pagano una volta sola all''apertura"]'::jsonb, 1, 'Nel 2026 il minimale è 18.808 € e i contributi fissi circa 4.521 € l''anno; i forfettari possono chiedere la riduzione del 35%.'),
  (137, 'professione', 'Nelle gare i giudici valutano soprattutto…', '["Il prezzo","Struttura, simmetria, pulizia e smile line","La marca dei prodotti","La velocità di pagamento"]'::jsonb, 1, 'Apex, curva a C, simmetria e pulizia sono decisivi.'),
  (138, 'onicofagia', 'Quale situazione è una controindicazione su unghie rosicchiate?', '["Unghie corte","Presenza di pus e gonfiore","Cuticole secche","Lamina sottile"]'::jsonb, 1, 'Infezione o infiammazione richiedono il medico, non una ricostruzione.'),
  (139, 'onicofagia', 'Perché si tira la cartina verso il basso su un''unghia rosicchiata?', '["Per risparmiare prodotto","Per spingere indietro la pelle rialzata e fare spazio all''allungamento","Per accorciare il letto","Per evitare il top"]'::jsonb, 1, 'Crea spazio per l''allungamento davanti all''unghia.'),
  (140, 'onicofagia', 'La causa più frequente della coilonichia (unghia a cucchiaio) è:', '["Carenza di ferro","Trauma da lima","Smalto scuro","Acetone"]'::jsonb, 0, 'Se compare da poco, si consiglia un controllo medico.'),
  (141, 'onicofagia', 'Con un''unghia ski-jump, cosa si fa prima di applicare il tip?', '["Si allunga di più","Si riduce la lunghezza naturale","Si lucida","Si applica il top"]'::jsonb, 1, 'Altrimenti il tip segue la curva verso l''alto.'),
  (142, 'onicofagia', 'Su un''unghia a pinza dolorante l''onicotecnica:', '["Accentua la curva a C","Fa il pinching","Indirizza a medico o podologo","Applica acrilico spesso"]'::jsonb, 2, 'La deformità comprime i tessuti: non si forza.'),
  (143, 'onicofagia', 'Su unghie grasse il ritiro del gel è legato soprattutto a:', '["Lampada nuova","Olio residuo sulla lamina","Colori chiari","Cartine di carta"]'::jsonb, 1, 'Disidratante, primer adatto e nuovo sgrassaggio prima della base.'),
  (144, 'onicofagia', 'Secondo una regola usata dai formatori, quanto dovrebbe essere lungo al massimo l''allungamento su un''unghia rosicchiata?', '["Il doppio del letto","Circa 1/3 della lunghezza della lamina","Uguale al letto","Non conta la lunghezza"]'::jsonb, 1, 'Una leva lunga su un''unghia piccola causa rotture e sollevamenti; si allunga poco alla volta.'),
  (145, 'onicofagia', 'Perché si taglia una piccola "U" nella cartina su un''unghia rosicchiata?', '["Per risparmiare carta","Per non premere sull''iponichio rialzato","Per fare la smile line","Per far colare il gel"]'::jsonb, 1, 'Il cuscinetto di pelle è vivo: la U evita pressione e dolore.'),
  (146, 'onicofagia', 'Su un''unghia rosicchiata resta uno spazio tra lamina e cartina. Cosa succede?', '["Niente","Il prodotto cola sotto e crea uno scalino debole e \"mordibile\"","Il gel polimerizza più in fretta","La curva a C migliora"]'::jsonb, 1, 'La cartina deve essere a filo del bordo, anche se il bordo quasi non c''è.'),
  (147, 'onicofagia', 'Perché nelle prime settimane gli appuntamenti sono più ravvicinati?', '["Per vendere di più","Le ricostruzioni su unghie molto rosicchiate durano meno e vanno controllate spesso","Perché il gel scade","Non serve"]'::jsonb, 1, 'Superficie di appoggio piccola e abitudine ancora presente: controlli frequenti, poi refill normali.'),
  (148, 'onicofagia', 'Un''unghia mostra una banda scura longitudinale comparsa da poco. Cosa fai?', '["La copri con il cover","La limi","Consigli una visita dal medico","La ignori"]'::jsonb, 2, 'Una banda scura nuova va sempre valutata dal medico: non spetta all''onicotecnica dire da cosa dipende.'),
  (149, 'onicofagia', 'Con un''unghia a cucchiaio, la cartina si posiziona:', '["Seguendo la conca","In asse con il dito, dopo aver livellato la conca","Verso l''alto","Non si usa la cartina"]'::jsonb, 1, 'Seguire la conca farebbe puntare l''allungamento verso l''alto.'),
  (150, 'cover-colori', 'A cosa serve principalmente il gel cover?', '["Lucidare","Allungare otticamente il letto ungueale e coprire imperfezioni","Sgrassare","Ammorbidire le cuticole"]'::jsonb, 1, 'È un costruttore pigmentato color pelle.'),
  (151, 'cover-colori', 'Perché i gel molto pigmentati vanno stesi sottili?', '["Per risparmiare","Perché il pigmento assorbe la luce e gli strati profondi polimerizzano male","Per un effetto opaco","Non serve"]'::jsonb, 1, 'Con strati spessi la parte profonda resta sotto-polimerizzata.'),
  (152, 'cover-colori', 'Il primo strato di un colore appare striato. È:', '["Un difetto del prodotto","Normale: il secondo strato uniforma","Segno di lampada rotta","Da rimuovere sempre"]'::jsonb, 1, 'Molti colori coprono al secondo strato sottile.'),
  (153, 'cover-colori', 'Quale NON è una causa di ritiro dai bordi?', '["Olio sulla lamina","Primer ancora umido sui lati","Lampada non compatibile","Uso di una cartina di carta"]'::jsonb, 3, 'Le prime tre sono cause tipiche di ritiro.'),
  (154, 'cover-colori', 'Il colore complementare del giallo, che lo neutralizza, è:', '["Viola","Verde","Arancio","Rosso"]'::jsonb, 0, 'Sono opposti sul cerchio cromatico.'),
  (155, 'cover-colori', 'Per un french con camouflage, la sequenza consigliata è:', '["Bianco prima, cover dopo","Cover prima, poi la smile line","Solo top","Solo bianco"]'::jsonb, 1, 'Si disegna la smile line sopra il cover.'),
  (156, 'cover-colori', 'Perché, in un french su letto allungato, si abbassano leggermente gli angoli della smile line?', '["Per risparmiare bianco","Per non lasciare zone trasparenti ai lati dove non c''è cover","Per allungare il bordo","Non si abbassano mai"]'::jsonb, 1, 'Se gli angoli salgono troppo, sotto il bianco restano piccole "orecchie" trasparenti.'),
  (157, 'cover-colori', 'Quali pigmenti assorbono più luce UV e sono più difficili da polimerizzare?', '["Bianco e blu","Rossi e neri","Solo i glitter","Tutti uguali"]'::jsonb, 1, 'Rossi e neri assorbono di più: strati sottili e tempi da scheda tecnica.'),
  (158, 'cover-colori', 'Uno strato di colore molto spesso si raggrinzisce dopo la lampada. Perché?', '["La lampada è troppo nuova","La superficie indurisce ma sotto il gel resta morbido","Il colore è scaduto","Manca il top"]'::jsonb, 1, 'La luce non arriva in fondo; un tempo più lungo non risolve uno strato troppo spesso.'),
  (159, 'cover-colori', 'Dove si sceglie il colore del cover?', '["Sotto la lampada UV","Alla luce naturale, appoggiando il tip sull''unghia","Al buio","Solo dal catalogo"]'::jsonb, 1, 'La luce naturale mostra il colore com''è; si confronta con il letto ungueale.'),
  (160, 'cover-colori', 'Perché si "sigilla" il bordo libero passando il colore sullo spessore della punta?', '["Per decorare","Per ridurre ritiro e scheggiature in punta","Per accelerare la lampada","Non serve"]'::jsonb, 1, 'Il colore avvolge il bordo e non si ritira.'),
  (161, 'cover-colori', 'Sotto uno smalto rosso o arancio, i dermatologi consigliano:', '["Nessuna base","Uno strato in più di base per evitare l''ingiallimento","Il top prima del colore","Acetone"]'::jsonb, 1, 'Indicazione dell''American Academy of Dermatology.'),
  (162, 'piedi', 'Rispetto alle mani, le unghie dei piedi crescono:', '["Più velocemente","Alla stessa velocità","A meno della metà della velocità","Non crescono"]'::jsonb, 2, 'Circa 1,6 contro 3,5 mm al mese in uno studio su giovani adulti.'),
  (163, 'piedi', 'Per prevenire l''unghia incarnita si taglia:', '["A punta","Molto corta e tonda","Dritta, angoli appena smussati","Scavando i lati"]'::jsonb, 2, 'Indicazione dei dermatologi (AAD).'),
  (164, 'piedi', 'Un''unghia gialla, ispessita e friabile:', '["Si copre con gel colorato","Si lima fino ad assottigliarla","Non si tratta: si consiglia medico o podologo","Si ricostruisce in acrilico"]'::jsonb, 2, 'Possibile micosi: controindicazione.'),
  (165, 'piedi', 'Chi tratta le unghie incarnite in Italia?', '["L''estetista","L''onicotecnica","Il podologo (o il medico)","Chiunque abbia una lima"]'::jsonb, 2, 'Il podologo è una professione sanitaria (DM 666/1994).'),
  (166, 'piedi', 'Cliente diabetica con una ferita al piede che non guarisce:', '["Pedicure con lama","Pediluvio caldo","Niente servizio, invio a medico o podologo","Semipermanente rinforzato"]'::jsonb, 2, 'Rischio di lesioni non percepite e infezioni.'),
  (167, 'piedi', 'La L. 1/1990 esclude dall''attività di estetista:', '["La manicure estetica","Le prestazioni con finalità terapeutica","Il trucco","Il massaggio estetico"]'::jsonb, 1, 'L''estetista lavora a scopo estetico.'),
  (168, 'piedi', 'Dopo ogni cliente, la vaschetta del pediluvio va:', '["Solo risciacquata","Svuotata, pulita con sapone, disinfettata per il tempo di contatto indicato, asciugata e registrata","Riempita con acqua calda","Spruzzata con profumo"]'::jsonb, 1, 'Senza pulizia il disinfettante funziona male; il tempo di contatto (es. 10 minuti in California) va rispettato.'),
  (169, 'piedi', 'Che consiglio si dà alla cliente prima di una pedicure?', '["Radersi le gambe la mattina stessa","Non radersi le gambe nelle 24 ore prima","Mettere crema grassa sulle unghie","Venire con lo smalto vecchio"]'::jsonb, 1, 'I microtagli del rasoio sono porte d''ingresso per i germi.'),
  (170, 'piedi', 'Quanto tempo può servire perché un''unghia dell''alluce si rinnovi del tutto?', '["2 settimane","1 mese","Fino a 12–18 mesi","10 anni"]'::jsonb, 2, 'Le unghie dei piedi crescono circa 1,6 mm al mese.'),
  (171, 'piedi', 'Con una cliente diabetica, la temperatura dell''acqua si controlla:', '["Chiedendo alla cliente","Con il termometro o con il proprio gomito","Con la punta del piede della cliente","Non serve controllarla"]'::jsonb, 1, 'Con la neuropatia la cliente può non sentire il calore e scottarsi.'),
  (172, 'piedi', 'Secondo il DM 666/1994, le callosità sono trattate da:', '["Estetista con lama","Podologo","Onicotecnica","Nessuno"]'::jsonb, 1, 'Il podologo tratta con metodi incruenti callosità, unghie ipertrofiche, deformi e incarnite.'),
  (173, 'piedi', 'Perché i pediluvi con tubature di ricircolo sono considerati più a rischio?', '["Consumano più acqua","Nelle tubature possono crescere micobatteri difficili da eliminare","Sono più rumorosi","Non sono più a rischio"]'::jsonb, 1, 'Indagine CDC in California: micobatteri in 29 vasche su 30.'),
  (174, 'arte-gare', 'Su cosa si applica la polvere chrome?', '["Gel colorato non polimerizzato","Top no-wipe polimerizzato","Base appiccicosa","Lamina nuda"]'::jsonb, 1, 'Poi si sigillano i bordi e si mette il top.'),
  (175, 'arte-gare', 'Nel cat-eye il magnete si usa:', '["Dopo il top","Prima di polimerizzare lo strato magnetico","Dopo la polimerizzazione","Non serve"]'::jsonb, 1, 'Le particelle si orientano finché il gel è fluido.'),
  (176, 'arte-gare', 'Nel one-stroke, per iniziare, il pennello piatto si carica:', '["Con un solo colore","Circa metà e metà con due colori","Fino alla ghiera","Asciutto"]'::jsonb, 1, 'Il colore non deve entrare nella ghiera.'),
  (177, 'arte-gare', 'In gara, il gel non polimerizzato a fine prova comporta:', '["−5 punti","Nessuna penalità","Squalifica","Un bonus"]'::jsonb, 2, 'È una regola tipica dei regolamenti Nailympia.'),
  (178, 'arte-gare', 'La "vista a tunnel" valuta soprattutto:', '["La smile line","La curva a C","Il colore","La lucentezza"]'::jsonb, 1, 'Si guarda l''unghia dalla punta.'),
  (179, 'arte-gare', 'In un''unghia con decorazione incapsulata, l''apex:', '["Non serve","Si costruisce sopra la decorazione","Va alla cuticola","Si sostituisce con glitter"]'::jsonb, 1, 'La struttura deve restare corretta.'),
  (180, 'arte-gare', 'Prima del top finale sul chrome, perché si passa un buffer leggero sul bordo libero?', '["Per accorciare l''unghia","Per togliere la polvere libera che impedirebbe al top di aderire","Per opacizzare il chrome","Non si fa mai"]'::jsonb, 1, 'La polvere libera sulla punta fa staccare il top.'),
  (181, 'arte-gare', 'Il gel per foil "non tiene" il foil. Causa probabile?', '["Strato troppo spesso o non polimerizzato abbastanza","Lampada troppo nuova","Foil troppo lucido","Colore sotto troppo chiaro"]'::jsonb, 0, 'Serve un velo sottile, polimerizzato fino a restare appiccicoso.'),
  (182, 'arte-gare', 'Dove conviene incapsulare una decorazione?', '["Alla cuticola","Sui lati","Nelle zone spesse: smile line, apex, centro della punta","Sul bordo libero"]'::jsonb, 2, 'Le zone sottili costringono a lasciare un rigonfiamento o a limare la decorazione.'),
  (183, 'arte-gare', 'In una gara Nailympia, cosa succede se pulisci le unghie della modella dopo lo stop?', '["Nulla","−5 punti","Squalifica","Bonus di pulizia"]'::jsonb, 2, 'Pulire mani o unghie con qualsiasi prodotto dopo la chiusura porta alla squalifica.'),
  (184, 'arte-gare', 'Nella scheda Nailympia 2026 French Twist 3 forme, quanto vale l''apex?', '["30 punti da solo","15 punti, valutato con la curva a C dallo stesso giudice","5 punti","Non è valutato"]'::jsonb, 1, 'Il giudice 3 assegna 15 punti alla curva a C e 15 all''apex: 30 in tutto.'),
  (185, 'arte-gare', 'Il gel cat-eye va "flashato" pochi secondi subito dopo il magnete perché:', '["Si secca il pennello","Le particelle continuano a muoversi e il disegno si perde","Il magnete si scarica","Il top non serve"]'::jsonb, 1, 'Un flash breve, un dito alla volta, fissa le particelle.')
